model.hubspot.hubspot__daily_ticket_hist.raw_code:
{{
    config(
        enabled=var('hubspot_service_enabled', False),
        materialized='incremental' if hubspot.is_incremental_compatible() else 'table',
        partition_by = {'field': 'date_day', 'data_type': 'date'}
            if target.type not in ('spark', 'databricks', 'duckdb') else ['date_day'],
        unique_key='ticket_day_id',
        incremental_strategy = 'insert_overwrite' if target.type not in ('snowflake', 'postgres', 'redshift') else 'delete+insert',
        file_format = 'delta'
    )
}}

{%- set change_data_columns = adapter.get_columns_in_relation(ref('int_hubspot__scd_daily_ticket_history')) -%}
{% set lookback_date = hubspot.hubspot_lookback(from_date='max(date_day)', datepart='day', interval=var('lookback_window', 3)) if is_incremental() %}

with change_data as (

    select *
    from {{ ref('int_hubspot__scd_daily_ticket_history') }}

{% if is_incremental() %}
    where date_day >= {{ lookback_date }}

-- If no issue fields have been updated since the last incremental run, the pivoted_daily_history CTE will return no record/rows.
-- When this is the case, we need to grab the most recent day's records from the previously built table so that we can persist 
-- those values into the future.

), most_recent_data as (

    select *
    from {{ this }}
    where date_day = (
        select max(date_day)
        from {{ this }}
        where date_day <= {{ lookback_date }}
    )
{% endif %}

), calendar as (

    select *
    from {{ ref('int_hubspot__ticket_calendar_spine') }}

    {% if is_incremental() %}
    where date_day >= {{ lookback_date }}
    {% endif %}

), pipeline as (

    select *
    from {{ ref('stg_hubspot__ticket_pipeline') }}

), pipeline_stage as (

    select *
    from {{ ref('stg_hubspot__ticket_pipeline_stage') }}

), joined as (

    select 
        calendar.source_relation,
        calendar.date_day,
        calendar.ticket_id
        {% if is_incremental() %}    
            {% for col in change_data_columns if col.name|lower not in ['source_relation','ticket_id','date_day','id'] %} 
            , coalesce(change_data.{{ col.name }}, most_recent_data.{{ col.name }}) as {{ col.name }}
            {% endfor %}

        {% else %}
            {% for col in change_data_columns if col.name|lower not in ['source_relation','ticket_id','date_day','id'] %} 
            , {{ col.name }}
            {% endfor %}
        {% endif %}

    from calendar
    left join change_data
        on calendar.ticket_id = change_data.ticket_id
        and calendar.date_day = change_data.date_day
        and calendar.source_relation = change_data.source_relation

    {% if is_incremental() %}
    left join most_recent_data
        on calendar.ticket_id = most_recent_data.ticket_id
        and calendar.date_day = most_recent_data.date_day
        and calendar.source_relation = most_recent_data.source_relation
    {% endif %}

), set_values as (

    select 
        source_relation,
        date_day,
        ticket_id

        {% for col in change_data_columns if col.name|lower not in ['source_relation','ticket_id','date_day','id'] %}
        , {{ col.name }}
        -- create a batch/partition once a new value is provided
        , sum(case when joined.{{ col.name }} is null then 0 else 1 end) over (
                partition by ticket_id {{ fivetran_utils.partition_by_source_relation(package_name='hubspot') }}
                order by date_day rows unbounded preceding) as {{ col.name }}_partition
        {% endfor %}

    from joined

), fill_values as (

    select 
        source_relation,
        date_day,
        ticket_id

        {% for col in change_data_columns if col.name|lower not in ['source_relation','ticket_id','date_day','id'] %}
        -- grab the value that started this batch/partition
        , first_value( {{ col.name }} ) over (
            partition by ticket_id, {{ col.name }}_partition {{ fivetran_utils.partition_by_source_relation(package_name='hubspot') }}
            order by date_day asc rows between unbounded preceding and current row) as {{ col.name }}
        {% endfor %}

    from set_values

), fix_null_values as (

    select 
        fill_values.source_relation,
        date_day,
        ticket_id,
        pipeline_stage.ticket_state,
        pipeline.pipeline_label as hs_pipeline_label,
        pipeline_stage.pipeline_stage_label as hs_pipeline_stage_label

        {% for col in change_data_columns if col.name|lower not in ['source_relation','ticket_id','date_day','id'] %} 
        -- we de-nulled the true null values earlier in order to differentiate them from nulls that just needed to be backfilled
        , case when  cast( {{ col.name }} as {{ dbt.type_string() }} ) = 'is_null' then null else {{ col.name }} end as {{ col.name }}
        {% endfor %}

    from fill_values

    left join pipeline
        on fill_values.hs_pipeline = pipeline.ticket_pipeline_id
        and fill_values.source_relation = pipeline.source_relation
    left join pipeline_stage
        on fill_values.hs_pipeline_stage = pipeline_stage.ticket_pipeline_stage_id
        and pipeline.ticket_pipeline_id = pipeline_stage.ticket_pipeline_id
        and fill_values.source_relation = pipeline_stage.source_relation

), surrogate as (

    select
        {{ dbt_utils.generate_surrogate_key(['date_day','ticket_id','source_relation']) }} as ticket_day_id,
        *

    from fix_null_values
)

select *
from surrogate

model.hubspot.hubspot__tickets.raw_code:
{{ config(enabled=var('hubspot_service_enabled', False)) }}

with ticket as (

    select *
    from {{ ref('stg_hubspot__ticket') }}

), ticket_pipeline as (

    select *
    from {{ ref('stg_hubspot__ticket_pipeline') }}

), ticket_pipeline_stage as (

    select *
    from {{ ref('stg_hubspot__ticket_pipeline_stage') }}

{% if var('hubspot_sales_enabled', true) and var('hubspot_deal_enabled', true) and var('hubspot_ticket_deal_enabled', false) %}
), ticket_deal as (

    select *
    from {{ ref('stg_hubspot__ticket_deal') }}

), deal as (

    select *
    from {{ ref('stg_hubspot__deal') }}

), join_deals as (

    select
        ticket_deal.source_relation,
        ticket_deal.ticket_id,
        ticket_deal.deal_id,
        deal.deal_name

    from ticket_deal
    left join deal 
        on ticket_deal.deal_id = deal.deal_id
        and ticket_deal.source_relation = deal.source_relation

), agg_deals as (

    select
        source_relation,
        ticket_id,
        {{ fivetran_utils.array_agg("case when deal_id is null then '' else cast(deal_id as " ~ dbt.type_string() ~ ") end") }} as deal_ids,
        {{ fivetran_utils.array_agg("case when deal_name is null then '' else deal_name end") }} as deal_names

    from join_deals
    group by 1,2

{% endif %}

{% if var('hubspot_sales_enabled', true) and var('hubspot_company_enabled', true) %}
), ticket_company as (

    select *
    from {{ ref('stg_hubspot__ticket_company') }}

), company as (

    select *
    from {{ ref('stg_hubspot__company') }}

), join_companies as (

    select
        ticket_company.source_relation,
        ticket_company.ticket_id,
        ticket_company.company_id,
        company.company_name

    from ticket_company
    left join company 
        on ticket_company.company_id = company.company_id
        and ticket_company.source_relation = company.source_relation

), agg_companies as (

    select
        source_relation,
        ticket_id,
        {{ fivetran_utils.array_agg("case when company_id is null then '' else cast(company_id as " ~ dbt.type_string() ~ ") end") }} as company_ids,
        {{ fivetran_utils.array_agg("case when company_name is null then '' else company_name end") }} as company_names

    from join_companies
    group by 1,2

{% endif %}

{% if var('hubspot_marketing_enabled', true) and var('hubspot_contact_enabled', true) %}
), ticket_contact as (

    select *
    from {{ ref('stg_hubspot__ticket_contact') }}

), contact as (

    select *
    from {{ ref('stg_hubspot__contact') }}

), join_contacts as (

    select
        ticket_contact.source_relation,
        ticket_contact.ticket_id,
        ticket_contact.contact_id,
        contact.email

    from ticket_contact
    left join contact 
        on ticket_contact.contact_id = contact.contact_id
        and ticket_contact.source_relation = contact.source_relation

), agg_contacts as (

    select
        source_relation,
        ticket_id,
        {{ fivetran_utils.array_agg("case when contact_id is null then '' else cast(contact_id as " ~ dbt.type_string() ~ ") end") }} as contact_ids,
        {{ fivetran_utils.array_agg("case when email is null then '' else email end") }} as contact_emails

    from join_contacts
    group by 1,2

{% endif %}

{% if var('hubspot_owner_enabled', true) %}
), owners_enhanced as (

    select *
    from {{ ref('int_hubspot__owners_enhanced') }}

{% endif%}

{% if var('hubspot_sales_enabled', true) and var('hubspot_engagement_enabled', true) %}
), engagement as (

    select *
    from {{ ref('hubspot__engagements') }}

), ticket_engagement as (

    select *
    from {{ ref('stg_hubspot__ticket_engagement') }}

), join_engagements as (

    select 
        engagement.source_relation,
        engagement.engagement_type,
        ticket_engagement.ticket_id
    from engagement
    inner join ticket_engagement
        on cast(engagement.engagement_id as {{ dbt.type_bigint() }}) = cast(ticket_engagement.engagement_id as {{ dbt.type_bigint() }} )
        and engagement.source_relation = ticket_engagement.source_relation

), agg_engagements as (

    {{ engagements_aggregated('join_engagements', 'ticket_id') }}

{% endif %}

), final_join as (

    select
        ticket.*,
        ticket_pipeline_stage.ticket_state,
        ticket_pipeline_stage.is_closed,
        ticket_pipeline_stage.pipeline_stage_label,
        ticket_pipeline.pipeline_label,
        ticket_pipeline_stage.display_order as pipeline_stage_order,
        ticket_pipeline.is_ticket_pipeline_deleted,
        ticket_pipeline_stage.is_ticket_pipeline_stage_deleted

    {% if var('hubspot_owner_enabled', true) %}
        , {{ dbt_utils.star(ref('int_hubspot__owners_enhanced'), except=["owner_id", "source_relation"], relation_alias="owners_enhanced") }}
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_deal_enabled', true) and var('hubspot_ticket_deal_enabled', false) %}
        , agg_deals.deal_ids
        , agg_deals.deal_names
    {% endif %}

    {% if var('hubspot_marketing_enabled', true) and var('hubspot_contact_enabled', true) %}
        , agg_contacts.contact_ids
        , agg_contacts.contact_emails
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_company_enabled', true) %}
        , agg_companies.company_ids
        , agg_companies.company_names
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_engagement_enabled', true) %}
        {% for metric in engagement_metrics() %}
        , coalesce(agg_engagements.{{ metric }},0) as {{ metric }}
        {% endfor %}
    {% endif %}

    from ticket

    left join ticket_pipeline 
        on cast(ticket.ticket_pipeline_id as {{ dbt.type_string() }}) = cast(ticket_pipeline.ticket_pipeline_id as {{ dbt.type_string() }})
        and ticket.source_relation = ticket_pipeline.source_relation

    left join ticket_pipeline_stage 
        on cast(ticket.ticket_pipeline_stage_id as {{ dbt.type_string() }}) = cast(ticket_pipeline_stage.ticket_pipeline_stage_id as {{ dbt.type_string() }})
        and cast(ticket_pipeline.ticket_pipeline_id as {{ dbt.type_string() }}) = cast(ticket_pipeline_stage.ticket_pipeline_id as {{ dbt.type_string() }})
        and ticket.source_relation = ticket_pipeline_stage.source_relation

    {% if var('hubspot_owner_enabled', true) %}
    left join owners_enhanced 
        on ticket.owner_id = owners_enhanced.owner_id
        and ticket.source_relation = owners_enhanced.source_relation
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_deal_enabled', true) and var('hubspot_ticket_deal_enabled', false) %}
    left join agg_deals 
        on ticket.ticket_id = agg_deals.ticket_id
        and ticket.source_relation = agg_deals.source_relation
    {% endif %}

    {% if var('hubspot_marketing_enabled', true) and var('hubspot_contact_enabled', true) %}
    left join agg_contacts
        on ticket.ticket_id = agg_contacts.ticket_id 
        and ticket.source_relation = agg_contacts.source_relation
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_company_enabled', true) %}
    left join agg_companies
        on ticket.ticket_id = agg_companies.ticket_id 
        and ticket.source_relation = agg_companies.source_relation
    {% endif %}

    {% if var('hubspot_sales_enabled', true) and var('hubspot_engagement_enabled', true) %}
    left join agg_engagements
        on ticket.ticket_id = agg_engagements.ticket_id
        and ticket.source_relation = agg_engagements.source_relation
    {% endif %}
)

select *
from final_join

model.hubspot.int_hubspot__scd_daily_tic.raw_code:
{{ config(materialized='table', enabled=var('hubspot_service_enabled', False)) }}

{%- set ticket_columns = adapter.get_columns_in_relation(ref('int_hubspot__pivot_daily_ticket_history')) -%}

with change_data as (

    select *
    from {{ ref('int_hubspot__pivot_daily_ticket_history') }}

), set_values as (

    select 
        source_relation,
        date_day, 
        ticket_id,
        id

        {% for col in ticket_columns if col.name|lower not in ['source_relation','date_day','ticket_id','id'] %} 
        , {{ col.name }} as {{ col.name|lower }}
        -- create a batch/partition once a new value is provided
        , sum( case when {{ col.name }} is null then 0 else 1 end) over (partition by ticket_id {{ fivetran_utils.partition_by_source_relation(package_name='hubspot') }}
            order by date_day rows unbounded preceding) as {{ col.name }}_field_partition

        {% endfor %}

    from change_data

), fill_values as (

-- each row of the pivoted table includes ticket property values if that property was updated on that day
-- we need to backfill to persist values that have been previously updated and are still valid 
    select 
        source_relation,
        date_day, 
        ticket_id,
        id

        {% for col in ticket_columns if col.name|lower not in ['source_relation','date_day','ticket_id','id'] %} 

        -- grab the value that started this batch/partition
        , first_value( {{ col.name }} ) over (
            partition by ticket_id, {{ col.name }}_field_partition {{ fivetran_utils.partition_by_source_relation(package_name='hubspot') }}
            order by date_day asc rows between unbounded preceding and current row) as {{ col.name }}

        {% endfor %}

    from set_values

)

select *
from fill_values

model.hubspot.int_hubspot__ticket_calend.raw_code:
{{
    config(
        enabled=var('hubspot_service_enabled', False),
        materialized='incremental' if hubspot.is_incremental_compatible() else 'table',
        partition_by = {'field': 'date_day', 'data_type': 'date'}
            if target.type not in ('spark', 'databricks', 'duckdb') else ['date_day'],
        unique_key='id',
        incremental_strategy = 'insert_overwrite' if target.type not in ('snowflake', 'postgres', 'redshift') else 'delete+insert',
        file_format = 'delta'
    )
}}
-- depends_on: {{ ref('stg_hubspot__ticket_tmp') }}

with calendar as (

    {% if execute and flags.WHICH in ('run', 'build') %}
        {% set first_date_query %}
            {% if is_incremental() %}
                select coalesce(max(date_day), cast('2016-01-01' as date)) from {{ this }}
            {% elif var('hubspot__daily_history_start_date', none) %}
                select cast('{{ var("hubspot__daily_history_start_date") }}' as date)
            {% else %}
                select coalesce(min(cast(property_createdate as date)), cast('2016-01-01' as date)) from {{ ref('stg_hubspot__ticket_tmp') }}
            {% endif %}
        {% endset %}
        {% set first_date = dbt_utils.get_single_value(first_date_query) | string %}

    {% else %}
        {% set first_date = "2016-01-01" %}
    {% endif %}

    {% set start_date = "cast('" ~ first_date[0:10] ~ "' as date)" %}

    select *
    from (
        {{
            dbt_utils.date_spine(
                datepart = "day",
                start_date = start_date,
                end_date = dbt.dateadd("day", 1, dbt.current_timestamp_in_utc_backcompat())
            )
        }}
    ) as date_spine

), ticket as (

    select 
        *,
        cast( {{ dbt.date_trunc('day', "case when closed_date is null then " ~ dbt.current_timestamp_backcompat() ~ " else closed_date end") }} as date) as open_until
    from {{ ref('stg_hubspot__ticket') }}
    where not coalesce(is_ticket_deleted, false)

), joined as (

    select
        cast(calendar.date_day as date) as date_day,
        ticket.ticket_id,
        ticket.source_relation
    from calendar
    inner join ticket
        on cast(calendar.date_day as date) >= cast(ticket.created_date as date)
        -- use this variable to extend the ticket's history past its close date (for reporting/data viz purposes :-)
        and cast(calendar.date_day as date) <= {{ dbt.dateadd('day', var('ticket_history_extension_days', 0), 'ticket.open_until') }}

), surrogate as (

    select
        *,
        {{ dbt_utils.generate_surrogate_key(['date_day','ticket_id','source_relation']) }} as id
    from joined

)

select *
from surrogate

model.hubspot.int_hubspot__pivot_daily_t.raw_code:
{{
    config(
        enabled=var('hubspot_service_enabled', False),
        materialized='incremental' if hubspot.is_incremental_compatible() else 'table',
        partition_by = {'field': 'date_day', 'data_type': 'date'}
            if target.type not in ('spark', 'databricks', 'duckdb') else ['date_day'],
        unique_key='id',
        incremental_strategy = 'insert_overwrite' if target.type not in ('snowflake', 'postgres', 'redshift') else 'delete+insert',
        file_format = 'delta'
    )
}}

{% set ticket_columns = (['hs_pipeline', 'hs_pipeline_stage'] + var('hubspot__ticket_property_history_columns', []))|unique|list %}

with daily_history as (

    select *
    from {{ ref('int_hubspot__daily_ticket_history') }}

    {% if is_incremental() %}
    where date_day >= {{ hubspot.hubspot_lookback(from_date='max(date_day)', datepart='day', interval=var('lookback_window', 3)) }}
    {% endif %}

), pivot_out as (

    select 
        source_relation,
        date_day, 
        ticket_id

        -- should we remove the `hs_` prefix? could introduce some duplicates if people already have something like `hs_owner` and `owner`
        {% for col in ticket_columns -%}
        , max(case when lower(field_name) = '{{ col|lower }}' then new_value end) as {{ dbt_utils.slugify(col) | replace(' ', '_') | lower }}
        {% endfor -%}

    from daily_history

    group by 1,2,3

), surrogate as (

    select 
        *,
        {{ dbt_utils.generate_surrogate_key(['source_relation','date_day', 'ticket_id']) }} as id
    from pivot_out
)

select *
from surrogate

