        {% endfor -%}

    from daily_history

    group by 1,2,3

), surrogate as (

    select
        *,
        {{ dbt_utils.generate_surrogate_key(['source_relation','date_day', 'contact_id']) }} as id
    from pivot_out
)

select *
from surrogate

